  function presetCard(b){const c=b.character;return `<article class="preset-card ${selectedBuild()?.id===b.id?'selected':''}" tabindex="0" role="button" aria-label="选择 ${esc(b.name)}" data-action="select-build" data-id="${esc(b.id)}">${portrait(c,"preset-portrait")}<div class="preset-info"><h3>${esc(c.name)}</h3><div class="subtitle">${esc(c.title)} · ${esc(c.series)}</div><p>${esc(c.skills.map(s=>s.name).join(' / '))} · ${esc(b.name)}</p><span class="color-label ${c.color}">${colors[c.color]}阵营</span><span class="small-text muted"> &nbsp; ${c.hp} 体力</span></div>${selectedBuild()?.id===b.id?'<span class="selected-check">✓ 已选择</span>':''}</article>`;}
  function renderHome(){const selected=selectedBuild();$('#main').innerHTML=`<div class="page-heading"><div><h1>欢迎来到心象实验室。</h1><p>选择一个角色，排列十三张心象，开始一次新的相遇。</p></div><span class="pill">● 内测开放中</span></div>
    <section class="hero"><div class="hero-copy"><span class="eyebrow">BUILD YOUR INNER WORLD</span><h2>你的心象，<br>不止一种<em>可能。</em></h2><p>在冷暖交错的世界里，以精神为锋，以记忆为序。<br>从一副十三张的心象牌组，写下你的角色故事。</p><div class="button-row">${btn('开始练习 <span aria-hidden="true">↗</span>','practice','', 'title="选择机器人数量与构筑，进行冷暖或人狼身份对抗"')}${btn('创建私人房间','create-room')}</div></div><div class="hero-art" role="img" aria-label="冷暖交融的心象世界插画"><span class="art-caption">THE WORLD BETWEEN MEMORIES</span></div></section>
    <div class="home-grid"><section><div class="section-heading"><h2>从一个心象开始 <small>CURATED CHARACTERS</small></h2><button class="text-button" data-nav="library">浏览全部 ${S.catalog.presets.length} 位角色 →</button></div><div class="preset-grid">${featuredBuilds().map(presetCard).join('')}</div>${S.builds.length?`<div class="section-heading" style="margin-top:24px"><h2>我的构筑 <small>YOUR COLLECTION</small></h2></div><div class="preset-grid">${S.builds.map(presetCard).join('')}</div>`:''}<div class="lower-banner"><span aria-hidden="true">◇</span><div><h3>还没有遇见属于你的角色？</h3><p>组合触发、条件与效果积木，创造角色与专属心象。</p></div>${btn('设计我的角色 →','new-build','ghost')}</div></section>
    <aside class="home-aside"><section class="quick-panel"><span class="eyebrow">A SEAT IS WAITING</span><h3>与朋友，一起入局。</h3><p>分享六位房间码，就能邀请朋友加入。<br>也可以让机器人陪你试试新构筑。</p><label>房间邀请码<input id="join-code" maxlength="6" autocomplete="off" placeholder="输入 6 位房间码" aria-label="六位房间邀请码"></label>${btn('加入房间 <span aria-hidden="true">→</span>','join-room','secondary')}<p class="help" style="margin:13px 0 0">当前构筑：${esc(selected?.name || '暂无')}<br>${S.user?'访问凭据保存在本浏览器；角色与房间存于服务器。':'首次游戏会自动登记一个本机旅人身份。'}</p>${!S.user?`<label style="margin-top:10px">你的昵称<input id="guest-name" maxlength="24" placeholder="旅人" value="${esc(readLocal('imaginary.name')||'')}"></label>`:''}</section><div class="rule-shortcut"><span>13</span><div><h4>十三张，依序展开</h4><p>A 到 K 各一张。心象可替代通常抽牌，<br>次序就是你的战术。</p></div></div><div class="rule-shortcut"><span>∞</span><div><h4>留下的牌，改变下一回合</h4><p>拳击、援药下回合成熟，其余默认立即成熟。<br>留住资源，也留住翻盘的可能。</p></div></div></aside></div>`;}
  function featuredBuilds(){const all=S.catalog.presets||[],packs=[...(S.catalog.contentPacks||[])].reverse(),picked=[];for(const pack of packs)for(const id of pack.characterIds.slice(0,3)){const b=all.find(b=>b.character.id===id);if(b&&!picked.includes(b))picked.push(b);}for(const b of all)if(picked.length<6&&!picked.includes(b))picked.push(b);return picked.slice(0,6);}
  function buildPicker(value=selectedBuild()?.id){return `<select id="build-picker" aria-label="选择出战构筑">${allBuilds().map(b=>`<option value="${esc(b.id)}" ${b.id===value?'selected':''}>${esc(b.name)} · ${esc(b.character.name)}${String(b.id).startsWith('preset_')?'（范例）':''}</option>`).join('')}</select>`;}
  function renderHistory(){if(!S.rooms.length||$('#room-history'))return;const states={lobby:'等待开始',playing:'正在对局',finished:'已结束'};$('#main').insertAdjacentHTML('beforeend',`<section class="panel" id="room-history" style="margin-top:25px"><div class="panel-title"><h2>再续一个故事</h2><span class="small-text muted">我参与的房间</span></div><div class="history-list">${S.rooms.slice(0,12).map(r=>`<div class="history-row"><div><b>${esc(r.name)}</b><small>${esc(r.code)} · ${S.catalog.modes[r.mode]} · ${states[r.status]||r.status}</small></div>${btn(r.status==='finished'?'查看复盘 →':'重新连接 →','reconnect-room','secondary small',`data-id="${esc(r.code)}"`)}</div>`).join('')}</div></section>`);}
  function buildPayload(id){return String(id).startsWith('preset_')?{presetId:id}:{buildId:id};}
